options.css:
@ .wizard-container {
	left: 50%;
	position: absolute;
}@ 
.wizard-timeline {
	content: "";
	height: 3px;
	margin-top: 35px;
	position: absolute;
	background-color: #00b4bd;
	z-index: 10;
	left: 0px;
}@ 
.wizard {
	height: 150px;
	padding-bottom: 15px;
	z-index: 30;
	left: 0px;
	position: absolute;
	color: #263645;
}@ 
.wizard td {
	text-align: center;
	font-size: 14px;
}@ 
.wizard td i {
	width: 50px;
	padding: 10px;
}@ 
.wizard td.text {
	text-transform: uppercase;
	white-space: pre-wrap;
	vertical-align: top;
	font-size: 12px;
}@ 
.wizard td.wizardSelected {
	color: White;
}@

@ .wizard-arrow {
background-color: white;
width: 0;
height: 0;
border-style: solid;
border-width: 20px 25px 0 25px;
border-color: #008998 transparent transparent transparent;
position: absolute;
top: -10px;
height: 9px;
left: 50%;
margin-left: -25px;
}@

@ .preview {
position: absolute;
left: 220px;
top: 0px;
}@ 
.preview td {
	text-align: left;
	font-size: 20pt;
height: 20px;
}@ 
.preview td.empty {
width: 42px;
}@ 
.preview td.split {
	font-size: 10pt;
	color: red;
}@ 
.dots {
	position: relative;
	left: 7px;
	top: 2px;
	border-left: dashed 1px red;
	height: 25px;
	width: 2px;
}@ 

.key {
	position: relative;
	float: left;
	left: 7px;
	top: 15px;
	border-left: solid 1px black;
	height: 15px;
	width: 2px;
}@ 
.key.right {
	float: right;
	left: inherit;
	right: 10px;
}@ 
.preview td.keystring {
	text-align: left;
	font-size: 10pt;
}@ 
.preview td.keystring.right {
	text-align: right;
}@ 
.elli {
	font-size: 10pt;
}@ 
span {
	padding: 3px;
}@ 
.preview td.docbordernone {
	height: 7px;
}@ 
.preview td.docborderend {
	border-bottom: solid 2px LightGray;
	border-left: solid 2px LightGray;
	height: 7px;
}@ 
.preview td.docborder {
	border-bottom: solid 2px LightGray;
	border-left: solid 2px LightGray;
	border-right: solid 2px LightGray;
	height: 7px;
}@ 

.preview td.doc {
	font-size: 10pt;
	text-align: center;
}@

